head.script:
scwin.gridView1_ongroupby = function(options) {
    scwin.groupbyFunc(options);
};
scwin.groupbyFunc = function(options) {
    /*
    	1. targetIndex 인수는 일부만 적용하면 안됩니다. 전체 적용 혹은 적용 하지 않음 으로 하세요.
    	2. 두번째 이상의 줄의 적용을 위해서는 이전 줄의 모든 셀을 더한 값이 targetIndex의 값이 됩니다.
    	3. 같은 줄에서 두개 이상의 옵션을 설정할 경우, colSpan된 셀을 하나로 세어야 합니다.
    	4. rowNumVisible, rowStatusVisible true일 경우
    	rowNum : rowStatus : 1 : 2 : 3 : 4
    					     5 : 6 : 7 : 8
    	형태로 됩니다. 
    	예를 들어 상단 샘플은 두번째 줄 옵션이 [a. 7개의 셀을 합침 b. 3개의 셀을 합침] 인데 b의 targetIndex는 a의 targetIndex(10) + a의 colSpan(7) = 17 이 아니라, a의 targetIndex(10) + a 셀의 개수(1) = 11이 됩니다.
     */
    options.groupbyHeader = [{
        colSpan: "4",
        inputType: "expression",
        expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ",
        align: "left"
    }];
    options.groupbyFooter = [{
        targetIndex: 0,
        value: "0"
    }, {
        targetIndex: 1,
        value: "1",
        colSpan: "2"
    }, {
        targetIndex: 2,
        inputType: "expression",
        expression: "SUM('sETC9')",
        dataType: "number"
    }, {
        targetIndex: 3,
        value: "3"
    }, {
        targetIndex: 4,
        value: "4"
    }, {
        targetIndex: 5,
        value: "5"
    }];
    gridView1.groupby(options); //실제 groupby 실행
};
scwin.trigger1_onclick = function(e) {
    var options = {};
    options.fileName = "test.xlsx";
    options.type = "0";
    options.startRowIndex = 0;
    options.startColumnIndex = 0;
    options.removeColumns = "1,3";
    options.groupby = "true";
    gridView1.advancedExcelDownload(options);
};
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_column39', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_13_2').innerText == '15455.9'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1').setTopRowIndex(20)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_7_2').innerText == '6026.2323'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
